#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Compact Refraction Table (Case Sheet)"
echo "=================================================="
echo ""
echo "Redesigns the OPD Case Sheet Refraction section:"
echo "  - Old: two separate tables (Distance, Near), each"
echo "    with RE/LE as ROWS -- lots of repeated headers"
echo "  - New: ONE table, RIGHT/LEFT as COLUMN GROUPS"
echo "    (SPH/CYL/AXIS/VA each), Dist./Near as rows"
echo "  - Matches the compact layout style from the"
echo "    reference printout (eyes side-by-side per row)"
echo "  - No database changes needed -- template-only edit"
echo ""

TARGET="app/print-templates/actions.js"

if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi

echo "Backing up current file to $TARGET.bak ..."
cp "$TARGET" "$TARGET.bak"

echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"

echo ""
echo "Verifying JS syntax ..."
node --check "$TARGET" && echo "  Syntax OK"

echo ""
echo "Done. Review the diff with:"
echo "  git diff $TARGET"
echo ""
echo "NOTE: If you have previously customized/saved the OPD Case"
echo "Sheet template via the in-app Print Templates editor, a row"
echo "already exists in the print_templates table for"
echo "template_key = 'opd_case_sheet', which OVERRIDES this code"
echo "default. To pick up this new layout you must either:"
echo "  (a) reset it from the Print Templates admin page ('Reset"
echo "      to default' for OPD Case Sheet), on BOTH production"
echo "      and training, OR"
echo "  (b) run this SQL on BOTH Supabase projects:"
echo "      delete from print_templates where template_key = 'opd_case_sheet';"
echo ""
